"""Tests for safe cleanup: only generated files are removed, backups restored."""

from envytweaks import config


def _patch_paths(monkeypatch, tmp_path, managed, legacy=()):
    xsetup = tmp_path / "sddm-Xsetup"
    xsetup_backup = config.backup_path(xsetup)
    monkeypatch.setattr(config, "MANAGED_PATHS", list(managed))
    monkeypatch.setattr(config, "LEGACY_PATHS", list(legacy))
    monkeypatch.setattr(config, "SDDM_XSETUP_PATH", xsetup)
    monkeypatch.setattr(config, "SDDM_XSETUP_BACKUP_PATH", xsetup_backup)
    return xsetup, xsetup_backup


def test_cleanup_removes_generated_and_keeps_user_file(monkeypatch, tmp_path) -> None:
    generated = tmp_path / "generated.conf"
    generated.write_text(f"# {config.GENERATED_MARKER}\n", encoding="utf-8")
    user_file = tmp_path / "user.conf"
    user_file.write_text("# user config\n", encoding="utf-8")
    _patch_paths(monkeypatch, tmp_path, [generated, user_file])

    config.cleanup()

    assert not generated.exists()
    assert user_file.read_text(encoding="utf-8") == "# user config\n"


def test_cleanup_dry_run_does_not_modify_files(monkeypatch, tmp_path, capsys) -> None:
    generated = tmp_path / "generated.conf"
    generated.write_text(f"# {config.GENERATED_MARKER}\n", encoding="utf-8")
    _patch_paths(monkeypatch, tmp_path, [generated])

    config.cleanup(dry_run=True)

    assert generated.exists()
    assert "Would remove file" in capsys.readouterr().out


def test_cleanup_restores_backup_on_reset(monkeypatch, tmp_path) -> None:
    target = tmp_path / "xorg.conf"
    target.write_text(f"# {config.GENERATED_MARKER}\n", encoding="utf-8")
    backup = config.backup_path(target)
    backup.write_text("user config\n", encoding="utf-8")
    _patch_paths(monkeypatch, tmp_path, [target])

    config.cleanup(restore_backups=True)

    assert target.read_text(encoding="utf-8") == "user config\n"
    assert not backup.exists()


def test_cleanup_does_not_overwrite_user_modified_file(monkeypatch, tmp_path) -> None:
    target = tmp_path / "xorg.conf"
    target.write_text("# user config\n", encoding="utf-8")
    backup = config.backup_path(target)
    backup.write_text("older config\n", encoding="utf-8")
    _patch_paths(monkeypatch, tmp_path, [target])

    config.cleanup(restore_backups=True)

    assert target.read_text(encoding="utf-8") == "# user config\n"
    assert backup.read_text(encoding="utf-8") == "older config\n"


def test_cleanup_removes_legacy_envycontrol_file(monkeypatch, tmp_path) -> None:
    legacy = tmp_path / "90-nvidia.conf"
    legacy.write_text("# Automatically generated by envycontrol\n", encoding="utf-8")
    _patch_paths(monkeypatch, tmp_path, [], [legacy])

    config.cleanup()

    assert not legacy.exists()


def test_cleanup_restores_sddm_xsetup(monkeypatch, tmp_path) -> None:
    xsetup, backup = _patch_paths(monkeypatch, tmp_path, [])
    xsetup.write_text(f"# {config.GENERATED_MARKER}\n", encoding="utf-8")
    backup.write_text("original script\n", encoding="utf-8")

    config.cleanup(restore_backups=True)

    assert xsetup.read_text(encoding="utf-8") == "original script\n"
    assert not backup.exists()


def test_cleanup_removes_generated_sddm_xsetup_without_backup(monkeypatch, tmp_path) -> None:
    xsetup, _backup = _patch_paths(monkeypatch, tmp_path, [])
    xsetup.write_text(f"# {config.GENERATED_MARKER}\n", encoding="utf-8")

    config.cleanup(restore_backups=True)

    assert not xsetup.exists()
